@Component
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
class ReportBuilder {                       // 有状态，每次需要新实例
    private final List<String> lines = new ArrayList<>();
    void add(String l) { lines.add(l); }
    String build() { return String.join("\n", lines); }
}

@Component
@RequestScope                               // 默认 proxyMode = TARGET_CLASS
class RequestContext { String traceId; }

@Service
@RequiredArgsConstructor
class ReportService {                       // singleton
    private final ObjectProvider<ReportBuilder> builders;   // 每次获取新的 prototype
    private final RequestContext ctx;                        // 注入的是代理，按当前请求取实例

    String report(List<String> data) {
        ReportBuilder b = builders.getObject();
        data.forEach(b::add);
        return ctx.traceId + "\n" + b.build();
    }
}

